<script setup lang="ts">
import { ref,onMounted } from 'vue';
import { ElButton } from 'element-plus';
import { useDesktop } from './store.ts';
const store=useDesktop(),connection=ref(''),items=ref<Array<{threadId:string;status:string;statusKnown:boolean}>>([]),cursor=ref<string|null>(null),selected=ref<Record<string,unknown>|null>(null),goal=ref<Record<string,unknown>|null>(null),busy=ref(false),error=ref(''),archived=ref(false),observedAt=ref('');
async function list(next=false){busy.value=true;error.value='';selected.value=null;goal.value=null;try{const value=await store.request('connections.get');connection.value=String(value.connectionId);const page=await store.request('threads.list',{connectionId:connection.value,limit:10,archived:archived.value,...(next&&cursor.value?{cursor:cursor.value}:{})});items.value=page.items as typeof items.value;cursor.value=page.nextCursor as string|null;observedAt.value=String(page.observedAt);}catch(cause){items.value=[];cursor.value=null;error.value=(cause as Error).message;}finally{busy.value=false;}}
async function inspect(threadId:string){busy.value=true;error.value='';selected.value=null;goal.value=null;try{selected.value=await store.request('threads.get',{connectionId:connection.value,threadId});goal.value=selected.value.goal as Record<string,unknown>;}catch(cause){error.value=(cause as Error).message;}finally{busy.value=false;}}
onMounted(()=>list());
</script>
<template>
  <section class="panel"><div class="section-heading"><h2>会话身份与状态</h2><ElButton :disabled="busy" @click="list()">刷新会话列表</ElButton></div><p class="muted">{{ store.mode==='fixture'?'确定性模拟会话，不代表真实会话。':'来自当前明确选择的本机 Codex 连接。' }}仅展示身份与状态，不显示标题、聊天正文或 Goal 目标正文。</p><label class="checkbox"><input v-model="archived" type="checkbox" aria-label="已归档会话" @change="list()" />查看已归档会话</label><p v-if="error" role="alert" class="notice">{{ error }}</p>
    <p v-if="busy" role="status">正在读取只读状态…</p><div class="table-scroll"><table v-if="items.length"><thead><tr><th>会话 ID</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="item in items" :key="item.threadId"><td class="mono">{{ item.threadId }}</td><td>{{ item.statusKnown?item.status:'未知 · '+item.status }}</td><td><ElButton :disabled="busy" @click="inspect(item.threadId)">读取状态与 Goal</ElButton></td></tr></tbody></table></div><p v-if="!items.length&&!busy&&!error" class="muted">已确认当前查询无会话。</p><div class="actions"><ElButton :disabled="busy||!cursor" @click="list(true)">下一页会话</ElButton><span class="muted">{{ observedAt?new Date(observedAt).toLocaleString():'' }}</span></div>
  </section>
  <section v-if="selected" class="panel"><h2>目标只读观察</h2><dl class="detail-grid"><dt>会话</dt><dd class="mono">{{ selected.threadId }}</dd><dt>状态</dt><dd>{{ selected.statusKnown?selected.status:'未知' }}</dd><dt>最新轮次</dt><dd>{{ (selected.latestTurn as {status?:string}|null)?.status||'确认无最新轮次' }}</dd><dt>当前 Goal</dt><dd>{{ goal?.availability==='known'?(goal.current?'已观察到 Goal 身份':'确认无当前 Goal'):'未知 · 未取得可靠证据' }}</dd><dt v-if="goal?.current">Goal 身份 / 状态</dt><dd v-if="goal?.current" class="mono">{{ (goal.current as {id:string;status:string}).id }} / {{ (goal.current as {id:string;status:string}).status }}</dd></dl><p class="notice">Goal 跨源账号绑定未证实；这些只读观察不确认任务完成，也不授予任何自动化权限。</p></section>
</template>
